import type { Change } from "../../types";

// quotePath off: accented paths come out as-is instead of "caf\303\251.ts"
export const GIT = ["git", "-c", "core.quotePath=false"];

// both lists are repo-root relative and cover the whole repo, whatever the cwd
export const DIFF_ARGS = [...GIT, "diff", "--numstat", "--no-renames", "HEAD"];
export const UNTRACKED_ARGS = [
  ...GIT,
  "ls-files",
  "--others",
  "--exclude-standard",
  "--full-name",
  ":/",
];

// `git diff --numstat` line: "<added>\t<deleted>\t<path>", "-" for binary
export const parseNumstat = (gitOutput: string): Change[] =>
  gitOutput
    .split("\n")
    .filter(Boolean)
    .map((line) => {
      const [addedField = "", deletedField = "", ...pathParts] = line.split("\t");
      return {
        path: pathParts.join("\t"),
        added: addedField === "-" ? null : Number(addedField),
        deleted: deletedField === "-" ? null : Number(deletedField),
        isNew: false,
      };
    });

export const parseUntracked = (gitOutput: string): Change[] =>
  gitOutput
    .split("\n")
    .filter(Boolean)
    .map((path) => ({ path, added: null, deleted: null, isNew: true }));

files.types/index.d.ts:
// added/deleted are null for binary files and untracked files
export type Change = { path: string; added: number | null; deleted: number | null; isNew: boolean }
// model/effort as the last main-loop request named them; effort absent for a model without one
export type ModelInfo = { model: string; effort?: string }
// one /context row, slimmed to what the pane draws; kind as ContextCategoryKind (the contract may not import it)
export type ContextSlice = { name: string; tokens: number; kind: 'used' | 'free' | 'buffer' | 'deferred' }
// the /context breakdown: its rows, the window they share, and the token count auto-compaction runs at (null when off);
// cacheReadPercent: the last response's input the prompt cache served, null before the first response
export type ContextInfo = {
  slices: ContextSlice[]
  maxTokens: number
  compactAt: number | null
  cacheReadPercent: number | null
}

declare module 'claude-code' {
  interface PluginState {
    session: {
      files: Change[]
      skills: string[]
      info: ModelInfo | null
      tick: number
      // the /context breakdown, estimated after each turn; null until the first one
      context: ContextInfo | null
      // folder paths the person folded in the Files tree (a click on the folder's line)
      collapsedFolders: string[]
    }
  }
}
